mapper.update:
UPDATE agent_session
SET status = 'RUNNING', started_at = COALESCE(started_at, #{now}), updated_at = #{now}
WHERE id = #{id}

UPDATE agent_session
SET status = 'RUNNING', started_at = COALESCE(started_at, #{now}), attempt_count = attempt_count + 1,
    next_retry_at = NULL, error_message = NULL, failure_type = NULL, retryable = 0,
    lease_until = #{leaseUntil}, last_heartbeat_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND lease_owner = #{owner}

UPDATE agent_session
SET status = 'RUNNING', next_retry_at = NULL, lease_until = #{leaseUntil},
    last_heartbeat_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND lease_owner = #{owner}

UPDATE agent_session
SET lease_until = #{leaseUntil}, last_heartbeat_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND lease_owner = #{owner} AND status = 'RUNNING'

UPDATE agent_session
SET lease_owner = NULL, lease_until = NULL, version = version + 1
WHERE id = #{id} AND lease_owner = #{owner}

UPDATE agent_session
SET status = #{newStatus}, updated_at = #{now}, version = version + 1
WHERE id = #{id} AND status = #{expectedStatus}

UPDATE agent_tool_call
SET result_summary = #{result}, status = #{status}, duration_ms = #{durationMs}, finished_at = #{finishedAt}
WHERE id = #{id}

